theme.css:
/* theme: Fractured Morning | Coalition leads hang by a thread while strikes cut power in Kyiv — the page splits down the middle, like a nation divided at dawn. */
/* mood: tense */
/* layout: hero=centered; major-events=numbered/masonry; political-news=lede/stack; financial-news=stat/grid-2; entertainment-news=outline/grid-2; sports=banner/grid-2; music-releases=plain/stack; stock-analysis=split/grid-2; outlook=timeline/stack */

.diary-page {
  --paper: #fbf3e0;
  --paper-alt: #f5e8c9;
  --ink: #1a150c;
  --ink-soft: #3d3422;
  --muted: #6b5c3a;
  --accent: #a34a00;
  --accent-ink: #fff8ec;
  --rule: #c9a86a;
  --font-display: var(--ff-bebas), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;

  background: 
    linear-gradient(180deg, transparent 0%, transparent 49%, var(--rule) 49%, var(--rule) 51%, transparent 51%, transparent 100%),
    var(--paper);
}

/* ————— Hero ————— */

.diary-page[data-hero="centered"] .diary-hero {
  background: var(--paper-alt);
  border-bottom: 2px solid var(--rule);
}

.diary-page[data-hero="centered"] .diary-hero-inner {
  padding-block: 3rem 4rem;
  position: relative;
}

.diary-page[data-hero="centered"] .diary-hero-inner::before {
  content: "⚖";
  display: block;
  font-size: 2rem;
  margin-bottom: 0.5rem;
  color: var(--accent);
}

.diary-page[data-hero="centered"] .diary-kicker {
  margin-top: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 0.3em;
  font-weight: 700;
}

.diary-page[data-hero="centered"] .diary-title {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 7vw, 5.5rem);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-weight: 700;
  max-width: none;
  line-height: 0.95;
  color: var(--ink);
}

.diary-page[data-hero="centered"] .diary-summary {
  font-size: clamp(1.1rem, 1.8vw, 1.35rem);
  max-width: 38rem;
  font-style: italic;
}

.diary-page[data-hero="centered"] .diary-theme-note {
  margin-top: 1.25rem;
}

.diary-page[data-hero="centered"] .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 0;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-size: 0.75rem;
}

/* ————— TOC ————— */

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 2px solid var(--rule);
}

.diary-page .diary-toc-number {
  font-family: var(--font-display);
  font-size: 0.9rem;
  letter-spacing: 0.05em;
}

.diary-page .diary-toc-link.is-active {
  color: var(--accent);
  font-weight: 700;
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-list {
    border-left: 2px solid var(--rule);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

/* ————— Sections ————— */

.diary-page .diary-section {
  padding-block: 3.5rem;
  border-top: 2px solid var(--rule);
}

.diary-page .diary-section:first-child {
  border-top: 0;
}

.diary-page .diary-section-head {
  border-bottom: 3px double var(--rule);
  padding-bottom: 0.75rem;
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-display);
  font-size: 1rem;
  letter-spacing: 0.15em;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3rem);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-weight: 700;
  line-height: 0.95;
}

/* ————— Cards ————— */

.diary-page .diary-card {
  position: relative;
}

.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.6rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 700;
  line-height: 1.05;
}

.diary-page .diary-card-thread {
  border-radius: 0;
  border-width: 2px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-size: 0.7rem;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Numbered: fractured index numbers */
.diary-page [data-card="numbered"] .diary-card-index {
  font-family: var(--font-display);
  font-size: 3.5rem;
  color: var(--accent);
  position: relative;
}

.diary-page [data-card="numbered"] .diary-card-index::after {
  content: "";
  display: block;
  width: 100%;
  height: 2px;
  background: var(--rule);
  margin-top: 0.25rem;
}

.diary-page [data-card="numbered"] .diary-card-inner {
  border-bottom: 1px solid var(--rule);
  padding-bottom: 1rem;
}

/* Lede */
.diary-page [data-card="lede"] .diary-card-lede {
  border-left-width: 4px;
  border-left-color: var(--accent);
  padding-left: 1.25rem;
  font-family: var(--font-body);
  font-size: 1.35rem;
  font-style: italic;
  line-height: 1.5;
}

/* Stat: figures in amber */
.diary-page [data-card="stat"] .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 10cqi, 3.75rem);
  color: var(--accent);
  letter-spacing: 0.03em;
}

.diary-page [data-card="stat"] .diary-card-inner {
  border-top-width: 4px;
}

/* Outline: double-rule boxes */
.diary-page [data-card="outline"] .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 0;
  padding: 1.5rem;
  box-shadow: 0.35rem 0.35rem 0 0 var(--rule);
}

.diary-page [data-card="outline"] .diary-card-inner:hover {
  box-shadow: 0.35rem 0.35rem 0 0 var(--accent);
  transition: box-shadow 200ms ease;
}

/* Banner: amber slabs with dark text */
.diary-page [data-card="banner"] .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 1.35rem;
  padding: 1rem 1.25rem;
  letter-spacing: 0.05em;
}

.diary-page [data-card="banner"] .diary-card-inner {
  border: 2px solid var(--accent);
  border-radius: 0;
}

.diary-page [data-card="banner"] .diary-card-thread {
  margin-top: 1rem;
  border-color: var(--accent);
}

/* Split: uneasy columns */
.diary-page [data-card="split"] .diary-card-inner {
  border-top: 0;
  padding-top: 0;
}

.diary-page [data-card="split"] .diary-card-title {
  border-top: 3px solid var(--accent);
  padding-top: 0.75rem;
}

/* Timeline: amber dots on a tense rail */
.diary-page [data-card="timeline"] .diary-card-inner::before {
  background: var(--rule);
  width: 1px;
  left: 0.2rem;
}

.diary-page [data-card="timeline"] .diary-card-inner::after {
  background: var(--accent);
  width: 0.65rem;
  height: 0.65rem;
  box-shadow: 0 0 0 4px var(--paper), 0 0 0 6px var(--rule);
}

/* ————— Prose ————— */

.diary-page .diary-prose {
  font-size: 1.1rem;
  line-height: 1.7;
}

.diary-page .diary-prose a {
  border-bottom: 1px solid currentColor;
  letter-spacing: 0.08em;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose blockquote {
  border-left: 4px solid var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
  width: 0.75rem;
  height: 1px;
  top: 0.8em;
}

/* ————— Markets ————— */

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-spark.is-down .diary-spark-change {
  color: var(--accent);
  font-weight: 700;
}

.diary-page .diary-spark-line polyline {
  stroke-width: 2;
}

/* ————— Footer ————— */

.diary-page .diary-footer {
  border-top: 2px solid var(--rule);
  font-weight: 600;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* ————— Split hero on wide screens: the lining-up of the fracture ————— */

@media (min-width: 40rem) {
  .diary-page[data-hero="centered"] .diary-hero-inner {
    padding-inline: 1.5rem;
  }
}

/* Cap the nowrap titles so a phone always fits them */
.diary-page .diary-card-title,
.diary-page .diary-section-title,
.diary-page .diary-title {
  overflow-wrap: anywhere !important;
}
